INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Blackbox-Tests nur für Endnutzer relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Entwickler nutzen sie"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Whitebox-Tests?', 3, '[{"text": "Code-internes Verhalten prüfen", "correct": true, "because": "Nutzt Code-Kenntnis"}, {"text": "Nur Eingaben testen", "correct": false, "because": "Blackbox-Fokus"}, {"text": "UI verbessern", "correct": false, "because": "Kein Design-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Testarten erfordern Code-Kenntnis?', 5, '[{"text": "Blackbox-Tests", "correct": false, "because": "Ohne Code-Einblick"}, {"text": "Whitebox-Tests", "correct": true, "because": "Nutzt Code-Struktur"}, {"text": "UI-Tests", "correct": false, "because": "Design-spezifisch"}, {"text": "Stress-Tests", "correct": false, "because": "Performance-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Blackbox-Tests prüfen Funktionalität. b) Sie benötigen Code-Zugriff.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Code-Zugriff nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Blackbox-Tests?', 4, '[{"text": "Funktionalität", "correct": false, "because": "Kern der Tests"}, {"text": "Eingaben/Ausgaben", "correct": false, "because": "Hauptfokus"}, {"text": "Code-Struktur", "correct": true, "because": "Nicht einsehbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Whitebox-Tests ohne Code-Zugriff möglich sind?', 2, '[{"text": "Nein", "correct": true, "because": "Code-Kenntnis erforderlich"}, {"text": "Ja", "correct": false, "because": "Definition widerspricht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt Blackbox-Testing?', 3, '[{"text": "Testen ohne Code-Einblick", "correct": true, "because": "Nur Eingaben prüfen"}, {"text": "Testen mit Code-Analyse", "correct": false, "because": "Whitebox"}, {"text": "Testen von UI-Design", "correct": false, "because": "Design-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Whitebox-Tests?', 5, '[{"text": "Code-Abdeckung prüfen", "correct": true, "because": "Internes Verhalten testen"}, {"text": "Fehlerquellen finden", "correct": true, "because": "Code-Struktur nutzen"}, {"text": "Schnellere Tests", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Blackbox-Tests sind nutzerorientiert. b) Sie ersetzen Whitebox-Tests. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzen, nicht ersetzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Blackbox-Tests?', 4, '[{"text": "Testfälle", "correct": false, "because": "Definieren Szenarien"}, {"text": "Spezifikationen", "correct": false, "because": "Grundlage der Tests"}, {"text": "Code-Zugriff", "correct": true, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Whitebox-Tests ohne Tools möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Manuell machbar"}, {"text": "Nein", "correct": false, "because": "Tools nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme lösen Blackbox-Tests?', 4, '[{"text": "Funktionalitätsfehler", "correct": true, "because": "Eingaben/Ausgaben prüfen"}, {"text": "Spezifikationsabweichung", "correct": true, "because": "Anforderungen testen"}, {"text": "Langsame Server", "correct": false, "because": "Performance-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Blackbox-Tests nur für QA sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Entwickler nutzen sie"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Whitebox-Tests?', 3, '[{"text": "Code-Abdeckung", "correct": true, "because": "Internes Verhalten prüfen"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Gründlichkeit zählt"}, {"text": "Viele Testfälle", "correct": false, "because": "Relevanz entscheidet"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Whitebox-Tests nutzen Code-Struktur. b) Sie garantieren fehlerfreien Code.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehlerfreiheit nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben Whitebox-Tests?', 5, '[{"text": "Höherer Aufwand", "correct": true, "because": "Code-Kenntnis nötig"}, {"text": "Abhängigkeit vom Code", "correct": true, "because": "Änderungen beeinflussen"}, {"text": "Langsamere Tests", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Blackbox-Tests unwichtig?', 3, '[{"text": "Eingaben", "correct": false, "because": "Kern der Prüfung"}, {"text": "Ausgaben", "correct": false, "because": "Ergebnisse testen"}, {"text": "Code-Interna", "correct": true, "because": "Nicht einsehbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht Whitebox-Tests die Testtiefe?', 3, '[{"text": "Ja", "correct": true, "because": "Code-Struktur prüfen"}, {"text": "Nein", "correct": false, "because": "Detaillierter"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Blackbox-Tests Robustheit verbessern?', 2, '[{"text": "Ja", "correct": true, "because": "Externes Verhalten testen"}, {"text": "Nein", "correct": false, "because": "Klarer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt Whitebox-Tests?', 4, '[{"text": "Code-Coverage-Tools", "correct": true, "because": "Misst Abdeckung"}, {"text": "UI-Designer", "correct": false, "because": "Design-Fokus"}, {"text": "Load-Tester", "correct": false, "because": "Performance-Fokus"}]');
